SELECT 
    (SELECT percentage FROM (SELECT state, percentage FROM (SELECT zip_code.state, COUNT(*) AS total_members, (COUNT(*) * 100.0 / (SELECT SUM(total_members) FROM (SELECT total_members FROM (SELECT zip_code.state, COUNT(*) AS total_members FROM member JOIN zip_code ON member.zip = zip_code.zip_code WHERE member.position = 'Member' GROUP BY zip_code.state)) AS subquery))) AS percentage FROM (SELECT zip_code.state, COUNT(*) AS total_members FROM member JOIN zip_code ON member.zip = zip_code.zip_code WHERE member.position = 'Member' GROUP BY zip_code.state) AS subquery) WHERE state = 'New Jersey') - 
    (SELECT percentage FROM (SELECT state, percentage FROM (SELECT zip_code.state, COUNT(*) AS total_members, (COUNT(*) * 100.0 / (SELECT SUM(total_members) FROM (SELECT total_members FROM (SELECT zip_code.state, COUNT(*) AS total_members FROM member JOIN zip_code ON member.zip = zip_code.zip_code WHERE member.position = 'Member' GROUP BY zip_code.state)) AS subquery))) AS percentage FROM (SELECT zip_code.state, COUNT(*) AS total_members FROM member JOIN zip_code ON member.zip = zip_code.zip_code WHERE member.position = 'Member' GROUP BY zip_code.state) AS subquery) WHERE state = 'Vermont') AS percentage_difference;

